                    for diff in new_diffs:
                        used_diffs.add(diff)
                    p[col] = row
                    used_rows[row] = True

                    if backtrack(col + 1):
                        return True

                    # Backtrack
                    used_rows[row] = False
                    for diff in new_diffs:
                        used_diffs.remove(diff)
