def girth(G):
    g = float('inf')
    for node in G.nodes():
        # BFS to find shortest cycle containing node
        dist = {node: 0}
        parent = {node: None}
        queue = [node]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    g = min(g, dist[u] + dist[v] + 1)
    return g

