def find_girth(G):
    girth = float('inf')
    for node in G.nodes():
        # BFS to find the shortest cycle containing 'node'
        dist = {node: 0}
        parent = {node: None}
        queue = [node]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Cycle found
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

