    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    parent = [-1] * n

    for i in range(n):
        if not visited[i]:
            stack = [(i, -1)]
            while stack:
                u, p = stack.pop()
                if visited[u]:
                    return True
                visited[u] = True
                for v in adj[u]:
                    if v != p:
                        stack.append((v, u))
    return False

