def solve_n_queens(n, fixed_values):
    # fixed_values is a dictionary {row: col}
    board = [-1] * n

    # Check if a queen can be placed at (row, col)
    def is_safe(row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == abs(r - row):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True

        if row in fixed_values:
            col = fixed_values[row]
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
            return False

        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    else:
        return None

