from pysat.solvers import Glucose3

def solve_with_sat():
    solver = Glucose3()

    # Variables: x_{v, l} is true if vertex v has label l
    # v in 0..9, l in 0..13
    # x_{v, l} = v * 14 + l + 1

    def get_var(v, l):
        return v * 14 + l + 1

    # Each vertex has exactly one label
    for v in range(10):
        solver.add_clause([get_var(v, l) for l in range(14)])
        for l1 in range(14):
            for l2 in range(l1 + 1, 14):
                solver.add_clause([-get_var(v, l1), -get_var(v, l2)])

    # Each label is used at most once
    for l in range(14):
        for v1 in range(10):
            for v2 in range(v1 + 1, 10):
                solver.add_clause([-get_var(v1, l), -get_var(v2, l)])

    # Edge labels must be distinct
    # Edge labels are |label(u) - label(v)|
    # Let y_{e, d} be true if edge e has label d, where d in 1..13
    # e in 0..12
    # y_{e, d} = 10 * 14 + e * 13 + d

    def get_edge_var(e, d):
        return 10 * 14 + e * 13 + d

    edges = []
    for g in range(5):
        edges.append((2*g, 2*g+1))
    for g in range(4):
        edges.append((2*g, 2*(g+1)))
        edges.append((2*g+1, 2*(g+1)+1))

    # Each edge has exactly one label
    for e in range(13):
        solver.add_clause([get_edge_var(e, d) for d in range(1, 14)])
        for d1 in range(1, 14):
            for d2 in range(d1 + 1, 14):
                solver.add_clause([-get_edge_var(e, d1), -get_edge_var(e, d2)])

    # Each label is used at most once for edges
    for d in range(1, 14):
        for e1 in range(13):
            for e2 in range(e1 + 1, 13):
                solver.add_clause([-get_edge_var(e1, d), -get_edge_var(e2, d)])

    # Link vertex labels to edge labels
    # For each edge (u, v), and each pair of labels (l1, l2),
    # if vertex u has label l1 and vertex v has label l2,
    # then the edge (u, v) must have label |l1 - l2|.

    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(14):
            for l2 in range(14):
                if l1 == l2: continue
                d = abs(l1 - l2)
                # If u has l1 and v has l2, then edge e_idx has label d
                # (-x_{u, l1} OR -x_{v, l2} OR y_{e_idx, d})
                solver.add_clause([-get_var(u, l1), -get_var(v, l2), get_edge_var(e_idx, d)])

    if solver.solve():
        model = solver.get_model()
        labels = [0] * 10
        for v in range(10):
            for l in range(14):
                if model[get_var(v, l) - 1] > 0:
                    labels[v] = l
        return labels
    else:
        return None

